// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.ListMemberOperator;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * GH-6140: a multi-value IN filter over a single statement pattern with a bound subject must not be rewritten into a
 * VALUES anchor.
 */
class FilterInValuesBoundSubjectTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI S = VF.createIRI("urn:s");
	private static final IRI P = VF.createIRI("urn:p");
	private static final IRI A = VF.createIRI("urn:a");
	private static final IRI B = VF.createIRI("urn:b");

	private static ListMemberOperator in(String var, IRI... values) {
		ListMemberOperator operator = new ListMemberOperator();
		operator.addArgument(Var.of(var));
		for (IRI value : values) {
			operator.addArgument(new ValueConstant(value));
		}
		return operator;
	}

	private static void optimize(TupleExpr root) {
		new FilterInValuesOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
	}

	@Test
	void constantSubjectKeepsMultiValueInFilter() {
		Filter filter = new Filter(new StatementPattern(Var.of("s", S), Var.of("p", P), Var.of("o")), in("o", A, B));
		QueryRoot root = new QueryRoot(filter);

		optimize(root);

		assertThat(root.getArg()).isSameAs(filter);
	}

	@Test
	void subjectBoundByOuterRowOfExistsKeepsMultiValueInFilter() {
		Filter inner = new Filter(new StatementPattern(Var.of("s"), Var.of("p", P), Var.of("o")), in("o", A, B));
		ValueExpr exists = new Exists(inner);
		Filter outer = new Filter(new StatementPattern(Var.of("s"), Var.of("q", P), Var.of("x")), exists);
		QueryRoot root = new QueryRoot(outer);

		optimize(root);

		assertThat(inner.getParentNode()).isSameAs(exists);
		assertThat(((Exists) exists).getSubQuery()).isSameAs(inner);
	}

	@Test
	void unboundSubjectIsStillRewrittenToValuesJoin() {
		Filter filter = new Filter(new StatementPattern(Var.of("s"), Var.of("p", P), Var.of("o")), in("o", A, B));
		QueryRoot root = new QueryRoot(filter);

		optimize(root);

		assertThat(root.getArg()).isNotSameAs(filter);
		assertThat(root.getArg().toString()).contains("Join");
	}

	@Test
	void singleValueIsStillAnchoredOnBoundSubject() {
		Filter filter = new Filter(new StatementPattern(Var.of("s", S), Var.of("p", P), Var.of("o")), in("o", A, A));
		QueryRoot root = new QueryRoot(filter);

		optimize(root);

		assertThat(root.getArg()).isNotSameAs(filter);
	}
}
